NEW_ENTRIES=[];GROUPS=[]

def block(key,cid,title,aliases,text,refs=None,kind='original'):
    rows=[line.split('|') for line in text.strip().splitlines()];assert len(rows)==4
    GROUPS.append((key,cid,title))
    for name,en,desc,recipe in rows:
        add(cid,title,f'{name}|{en}|{desc}。')
        e=CATALOG[-1];e.update(scholar_myth_v53_reference=True,expansion_group=key,added_in='53.0',age_min=25,adult_only=True,minor_reference=False,illustration_recipe=recipe,reference_mode=kind,
          aliases=[*aliases,title],note=('地域服饰结构的原创绘画示意，参看所列馆藏；不代表一个族群的全部服装。' if kind=='regional' else '基于神话标志物的原创角色重设计，不复刻现成游戏、影视或漫画人设。' if kind=='myth' else '成年原创角色的外观、衣物与表演参考；衣着用于交代身份、环境和气质。'))
        if refs:e['reference_ids']=refs
        NEW_ENTRIES.append(e)

