def make_v53_combinations(entries):
    out=[]
    for key,cid,title in GROUPS:
        es=[e for e in entries if e.get('expansion_group')==key and e.get('scholar_myth_v53_reference')]
        assert len(es)==4
        out.append({'name':'主题图集·'+title,'description':'四种代表外观供比较和选择；各套独立成立，可另存后继续收集部件。','palette':'以选中的代表外观为主，比较衣层、材质、标志物与神态。','entry_ids':[e['id'] for e in es],'theme_reference':True,'added_in':'53.0'})
    return out
